// Lines that start with // are notes for people. The app skips them.
script "My hide and seek" for hideseek v1

// Every player has a brain: a small neural network.
// hideseek-starter sees eight distance rays, its speed, whether the other
// player is in sight, whether it is the prep phase and the nearest ramp.
brain hideseek-starter

// This block runs for every player, hider and seeker, 30 times per second.
each tick {
  // act sets how the player moves, turns, grabs and locks in the next step.
  act(move: brain.move, turn: brain.turn, grab: 0, lock: 0)

  // One script trains both teams, so first check which team this player is on.
  if agent.isHider {
    // A point for every second the seeker cannot see the hider.
    reward +1 * dt when agent.hidden
    // And loses one for every second the seeker has it in sight.
    reward -1 * dt when agent.seen
  }
}
